CREATE TABLE market_ingestion_queue(id BIGSERIAL PRIMARY KEY,source_id BIGINT NOT NULL REFERENCES data_sources(id),exchange_code VARCHAR(10) NOT NULL CHECK(exchange_code IN ('NSE','BSE')),job_type VARCHAR(32) NOT NULL CHECK(job_type IN ('daily-candles','corporate-actions','market-sessions')),artifact_name VARCHAR(255) NOT NULL,artifact_sha256 CHAR(64) NOT NULL,csv_payload BYTEA NOT NULL,state VARCHAR(20) NOT NULL DEFAULT 'PENDING',attempts INT NOT NULL DEFAULT 0,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT now(),locked_at TIMESTAMPTZ,last_error TEXT,completed_at TIMESTAMPTZ,UNIQUE(source_id,job_type,artifact_sha256));
CREATE INDEX idx_market_queue_due ON market_ingestion_queue(next_attempt_at,id) WHERE state IN ('PENDING','RETRY');
CREATE TABLE market_worker_executions(id BIGSERIAL PRIMARY KEY,queue_id BIGINT REFERENCES market_ingestion_queue(id),job_name VARCHAR(80) NOT NULL,started_at TIMESTAMPTZ NOT NULL DEFAULT now(),finished_at TIMESTAMPTZ,status VARCHAR(20) NOT NULL,attempt INT NOT NULL,error_message TEXT);
CREATE TABLE instrument_source_freshness(instrument_id BIGINT NOT NULL REFERENCES instruments(id),source_id BIGINT NOT NULL REFERENCES data_sources(id),last_synced_at TIMESTAMPTZ NOT NULL,latest_candle_at TIMESTAMPTZ,source_revision VARCHAR(120),PRIMARY KEY(instrument_id,source_id));
CREATE UNIQUE INDEX uq_active_source_stale ON data_quality_events(instrument_id,source_id,event_type) WHERE event_type='SOURCE_STALE' AND resolved_at IS NULL;
